input.sparql:
PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <https://w3id.org/serp/ref#>
SELECT ?s ?ts WHERE {
  ?z brick:hasTag "Perimeter_top_ZN_3" .
  ?p brick:isPointOf ?z ;
     a brick:OccupancySensor ;
     ref:hasTimeseriesId ?ts .
}

PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <https://w3id.org/serp/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?name ?ts WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?name FILTER (?name="Perimeter_top_ZN_3") .
  ?p brick:isPointOf ?z ;
     a brick:OccupancySensor ;
     ref:hasTimeseriesId ?ts .
}

PREFIX brick: <http://brickschema.org/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?name WHERE {
  ?z rdfs:label ?name FILTER (CONTAINS(?name,"Perimeter"))
}

PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <https://w3id.org/serp/ref#>
SELECT ?p ?ts WHERE {
  ?p brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02> ;
     ref:hasTimeseriesId ?ts .
}
